-- Run once AFTER deploying assets, creating the game, and importing the CSV.

-- Sets image URLs only. Does not create records, change compatibility, or publish the game.

-- Exact game/name/slot matches; no UPDATE is applied unless the complete expected roster exists.

-- Temporary mapping tables are connection-local and removed below.

SET NAMES utf8;

START TRANSACTION;

SET @warzone_game_id = CONVERT(X'43616c6c206f662044757479205761727a6f6e65' USING utf8);

CREATE TEMPORARY TABLE warzone_weapon_images (
  asset_id VARCHAR(64) NOT NULL PRIMARY KEY,
  name VARCHAR(128) NOT NULL,
  slot VARCHAR(64) NOT NULL,
  image_url VARCHAR(128) NOT NULL,
  thumb_url VARCHAR(128) NOT NULL
) ENGINE=InnoDB DEFAULT CHARACTER SET utf8 COLLATE utf8_bin;



CREATE TEMPORARY TABLE warzone_attachment_images (
  asset_id VARCHAR(64) NOT NULL PRIMARY KEY,
  name VARCHAR(128) NOT NULL,
  slot VARCHAR(64) NOT NULL,
  image_url VARCHAR(128) NOT NULL,
  thumb_url VARCHAR(128) NOT NULL
) ENGINE=InnoDB DEFAULT CHARACTER SET utf8 COLLATE utf8_bin;


















CREATE TEMPORARY TABLE warzone_image_guard (ok INT NOT NULL PRIMARY KEY) ENGINE=InnoDB;

SELECT 1 WHERE
  (SELECT COUNT(*) FROM games WHERE BINARY id = BINARY @warzone_game_id) = 1
  AND (SELECT COUNT(*) FROM weapons WHERE BINARY game_id = BINARY @warzone_game_id) = 270
  AND (SELECT COUNT(*) FROM attachments WHERE BINARY game_id = BINARY @warzone_game_id) = 3279
  AND (SELECT COUNT(DISTINCT m.asset_id) FROM warzone_weapon_images m JOIN weapons w
       ON BINARY w.name = BINARY m.name WHERE BINARY w.game_id = BINARY @warzone_game_id) = 270
  AND (SELECT COUNT(DISTINCT m.asset_id) FROM warzone_attachment_images m JOIN attachments a
       ON BINARY a.name = BINARY m.name AND BINARY a.slot = BINARY m.slot
       WHERE BINARY a.game_id = BINARY @warzone_game_id) = 3279;

UPDATE weapons w JOIN warzone_weapon_images m ON BINARY w.name = BINARY m.name
JOIN warzone_image_guard g ON g.ok = 1
SET w.image_url = m.image_url, w.thumb_url = m.thumb_url, w.updated_at = CURRENT_TIMESTAMP
WHERE BINARY w.game_id = BINARY @warzone_game_id;

UPDATE attachments a JOIN warzone_attachment_images m
ON BINARY a.name = BINARY m.name AND BINARY a.slot = BINARY m.slot
JOIN warzone_image_guard g ON g.ok = 1
SET a.image_url = m.image_url, a.thumb_url = m.thumb_url, a.updated_at = CURRENT_TIMESTAMP
WHERE BINARY a.game_id = BINARY @warzone_game_id;

UPDATE games JOIN warzone_image_guard g ON g.ok = 1
SET image_url = CONVERT(X'75706c6f6164732f43616c6c2b6f662b447574792b5761727a6f6e652d617274776f726b2d32303236313031312e706e67' USING utf8), thumb_url = CONVERT(X'75706c6f6164732f7468756d622f43616c6c2b6f662b447574792b5761727a6f6e652d617274776f726b2d32303236313031312e706e67' USING utf8), header_url = CONVERT(X'75706c6f6164732f6865616465722f43616c6c2b6f662b447574792b5761727a6f6e652d617274776f726b2d32303236313031312e706e67' USING utf8), updated_at = CURRENT_TIMESTAMP
WHERE BINARY id = BINARY @warzone_game_id;

SELECT CASE WHEN EXISTS (SELECT 1 FROM warzone_image_guard WHERE ok = 1)
  THEN 'Warzone image URLs linked: 270 weapons, 3279 attachments and game artwork.'
  ELSE 'NO CHANGES: game or complete expected weapon/attachment roster is missing.' END AS result;

DROP TEMPORARY TABLE warzone_image_guard, warzone_weapon_images, warzone_attachment_images;

COMMIT;
